"""Execute author tests against generated bytes; forbid actual custody and network."""
import json
from pathlib import Path
import sys
import unittest

HERE = Path(__file__).resolve().parent
violations = []


def audit(event, args):
    if event.startswith('socket.') or event in ('urllib.Request', 'subprocess.Popen'):
        violations.append(event)
        raise RuntimeError('FORBIDDEN_TEST_OPERATION')
    if event == 'open' and isinstance(args[0], (str, bytes)):
        path = str(args[0])
        if '/projection-custody/' in path or '/li-v3-custody/' in path:
            violations.append('PRIVATE_SOURCE_OPEN')
            raise RuntimeError('FORBIDDEN_TEST_OPERATION')


sys.addaudithook(audit)
suite = unittest.defaultTestLoader.discover(str(HERE), pattern='test_reference_projector.py')
result = unittest.TextTestRunner(verbosity=2).run(suite)
print(json.dumps({'tests_run': result.testsRun, 'failures': len(result.failures),
                  'errors': len(result.errors), 'skipped': len(result.skipped),
                  'forbidden_events': violations}, sort_keys=True))
raise SystemExit(0 if result.wasSuccessful() and not violations else 1)
